sys_ws_operation.operation_script:
(function process(request, response) {
  function countRecords(table, query) {
    var ga = new GlideAggregate(table);
    if (query) ga.addEncodedQuery(query);
    ga.addAggregate("COUNT");
    ga.query();
    ga.next();
    return parseInt(ga.getAggregate("COUNT") || "0", 10);
  }

  var PO = "x_2056099_indust_0_production_order";
  var REQ = "x_2056099_indust_0_inv_req";
  var ALERT = "x_2056099_indust_0_inv_alert";
  var RES = "x_2056099_indust_0_prod_res";

  response.setBody({
      activeOrders: countRecords(PO, "active=true"),
      inProgressOrders: countRecords(PO, "status=in_production"),
      plannedOrders: countRecords(PO, "status=planned"),
      pendingRequests: countRecords(REQ, "statusNOT INcompleted,cancelled,rejected"),
      activeAlerts: countRecords(ALERT, "statusNOT INresolved,dismissed"),
      criticalAlerts: countRecords(ALERT, "severity=critical^statusNOT INresolved,dismissed"),
      availableResources: countRecords(RES, "active=true^status=available"),
      maintenanceRequired: countRecords(RES, "maintenance_required=true")
  });
})(request, response);
